```cpp
inline bool GetIntersectPoint(const Point64& ln1a, const Point64& ln1b,
	const Point64& ln2a, const Point64& ln2b, PointD& ip)
{
	// https://en.wikipedia.org/wiki/Line%E2%80%93line_intersection
	double m1, b1, m2, b2;
	if (ln1b.x == ln1a.x)
	{
		if (ln2b.x == ln2a.x) return false;
		m2 = static_cast<double>(ln2b.y - ln2a.y) /
			static_cast<double>(ln2b.x - ln2a.x);
		b2 = ln2a.y - m2 * ln2a.x;
		ip.x = static_cast<double>(ln1a.x);
		ip.y = m2 * ip.x + b2;
	}
	else if (ln2b.x == ln2a.x)
	{
		m1 = static_cast<double>(ln1b.y - ln1a.y) /
			static_cast<double>(ln1b.x - ln1a.x);
		b1 = ln1a.y - m1 * ln1a.x;
		ip.x = static_cast<double>(ln2a.x);
		ip.y = m1 * ip.x + b1;
	}
	else
	{
		m1 = static_cast<double>(ln1b.y - ln1a.y) /
			static_cast<double>(ln1b.x - ln1a.x);
		b1 = ln1a.y - m1 * ln1a.x;
		m2 = static_cast<double>(ln2b.y - ln2a.y) /
			static_cast<double>(ln2b.x - ln2a.x);
		b2 = ln2a.y - m2 * ln2a.x;
		if (std::fabs(m1 - m2) > floating_point_tolerance)
		{
			ip.x = (b2 - b1) / (m1 - m2);
			ip.y = m1 * ip.x + b1;
		}
		else
		{
			ip.x = static_cast<double>(ln1a.x + ln1b.x) * 0.5;
			ip.y = static_cast<double>(ln1a.y + ln1b.y) * 0.5;
		}
	}
	return true;
}
```

