pub fn cpp_double(v: f64) -> String {
    if v.is_nan() { return "nan".into(); } // cout prints "nan"
    if v.is_infinite() { return if v>0 {"inf"} else {"-inf"}.into(); }
    // %g with precision 6
    let s = format!("{:.5e}", v); // e.g. "-5.30200e3", "1.00000e6", "0.00000e0"
    // parse
    let (mant, exp) = s.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let neg = mant.starts_with('-');
    let digits: String = mant.chars().filter(|c| c.is_ascii_digit()).collect(); // 6 digits
    // value = digits[0].digits[1..6] * 10^exp
    if exp < -4 || exp >= 6 {
        // scientific: d.ddddd with trailing zeros stripped, e+XX (at least 2 digits)
        let mut m = String::new();
        if neg { m.push('-'); }
        m.push(digits.as_bytes()[0] as char);
        let frac = digits[1..].trim_end_matches('0');
        if !frac.is_empty() { m.push('.'); m.push_str(frac); }
        let sign = if exp < 0 { '-' } else { '+' };
        format!("{}e{}{:02}", m, sign, exp.abs())
    } else {
        // fixed: decimal point after position exp+1
        let mut out = String::new();
        if neg { out.push('-'); }
        if exp >= 0 {
            let ip = exp as usize + 1;
            out.push_str(&digits[..ip]);
            let frac = digits[ip..].trim_end_matches('0');
            if !frac.is_empty() { out.push('.'); out.push_str(frac); }
        } else {
            out.push_str("0.");
            for _ in 0..(-exp - 1) { out.push('0'); }
            let frac = digits.trim_end_matches('0');
            out.push_str(frac);
        }
        out
    }
}
