use crate::geom::*;

#[derive(Clone, Copy, PartialEq)]
pub enum JoinType { Miter, Round, Square }
#[derive(Clone, Copy, PartialEq)]
pub enum EndType { Polygon, Joined, Butt, Round, Square }

const DEFAULT_ARC_TOLERANCE: f64 = 0.25;

fn get_unit_normal(pt1: Point64, pt2: Point64) -> PointD {
    let mut dx = (pt2.x - pt1.x) as f64;
    let mut dy = (pt2.y - pt1.y) as f64;
    if dx == 0.0 && dy == 0.0 { return PointD::new(0.0, 0.0); }
    let f = 1.0 / dx.hypot(dy);
    dx *= f; dy *= f;
    PointD::new(dy, -dx)
}

fn strip_duplicates(path: &Path64, is_closed: bool) -> Path64 {
    // Clipper2 StripDuplicates
    let mut out: Path64 = Vec::with_capacity(path.len());
    for &pt in path {
        if out.last() != Some(&pt) { out.push(pt); }
    }
    if is_closed {
        while out.len() > 1 && out.first() == out.last() { out.pop(); }
    }
    out
}
