fn do_round(pt: Point64, n_k: PointD, n_j: PointD, angle: f64, steps_per_rad: f64, delta: f64, out: &mut Path64) {
    let steps = (steps_per_rad * angle.abs()).ceil() as i32; // static_cast<int> of ceil
    let step_sin = (angle / steps as f64).sin();
    let step_cos = (angle / steps as f64).cos();
    let mut pt2 = PointD::new(n_k.x * delta, n_k.y * delta);
