        out.push(Point64::from_doubles(pt.x as f64 + pt2.x, pt.y as f64 + pt2.y));
        pt2 = PointD::new(pt2.x*step_cos - step_sin*pt2.y, pt2.y*step_cos + pt2.x*step_sin);
    }
    out.push(Point64::from_doubles(pt.x as f64 + pt2.x, pt.y as f64 + pt2.y));
}
