/// `std::stoi` semantics: skip leading whitespace, optional sign, then
/// decimal digits; trailing characters are ignored. Returns `None` when
/// no digits are present or the value overflows (C++ would throw).
fn stoi(s: &str) -> Option<i64> {
    let b = s.trim_start().as_bytes();
    let mut i = 0;
    let mut neg = false;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        neg = b[i] == b'-';
        i += 1;
    }
    let start = i;
    let mut val: i64 = 0;
    while i < b.len() && b[i].is_ascii_digit() {
        val = val.checked_mul(10)?.checked_add((b[i] - b'0') as i64)?;
        i += 1;
    }
    if i == start {
        return None;
    }
    Some(if neg { -val } else { val })
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let offset: i64 = if args.len() > 1 {
        match stoi(&args[1]) {
            Some(v) => v,
            None => {
                // mimic an uncaught std::invalid_argument / std::out_of_range
                eprintln!("terminate called after throwing an instance of 'std::invalid_argument'");
                eprintln!("  what():  stoi");
                std::process::exit(134); // SIGABRT
            }
        }
    } else {
        10
    };

    let square: Path64 = vec![
        Point64::new(0, 0),
        Point64::new(100, 0),
        Point64::new(100, 100),
        Point64::new(0, 100),
    ];
    let triangle: Path64 = vec![
        Point64::new(50, 0),
        Point64::new(100, 100),
        Point64::new(0, 100),
    ];

    let subjects: Paths64 = vec![square];
    let clips: Paths64 = vec![triangle];

    let intersected = intersect(&subjects, &clips, FillRule::EvenOdd);
    let offset_result = inflate_paths(
        &intersected,
        offset as f64,
        JoinType::Round,
        EndType::Polygon,
    );

    if !offset_result.is_empty() && !offset_result[0].is_empty() {
        let area = area(&offset_result[0]);
        let bounds = get_bounds(&offset_result);
        let _width = bounds.right - bounds.left;
        let _height = bounds.bottom - bounds.top;

        println!("{}", cpp_double(area));
    } else {
        println!("0");
    }
}

